def _runs(indices):
    runs = []
    for x in indices:
        if not runs or x != runs[-1][-1] + 1:
            runs.append([x])
        else:
            runs[-1].append(x)
    return runs

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Vertical 5-lines: repeat the colored rectangle attached to the right.
    for c in range(w):
        for spine in _runs([r for r in range(h) if grid[r][c] == 5]):
            if len(spine) < 2:
                continue
            top, bottom = spine[0], spine[-1]
            seed_end = next((r for r in range(bottom, top - 1, -1)
                             if any(grid[r][j] for j in range(c + 1, w))), None)
            if seed_end is None:
                continue
            seed_start = seed_end
            while seed_start > top and any(grid[seed_start - 1][j] for j in range(c + 1, w)):
                seed_start -= 1
            right = max(j for j in range(c + 1, w)
                        if any(grid[r][j] for r in range(seed_start, seed_end + 1)))
            pat = [[grid[r][j] for j in range(c + 1, right + 1)]
                   for r in range(seed_start, seed_end + 1)]
            for r in spine:
                # At the top of the line, use the top row of the seed motif.
                row = pat[(r - top) % len(pat)]
                for j, value in enumerate(row, c + 1):
                    out[r][j] = value

    # Horizontal 5-lines: repeat the colored rectangle attached below.
    for r in range(h):
        for spine in _runs([c for c in range(w) if grid[r][c] == 5]):
            if len(spine) < 2:
                continue
            left, right = spine[0], spine[-1]
            seed_end = next((rr for rr in range(h - 1, r, -1) if grid[rr][left] != 0), None)
            if seed_end is None:
                continue
            seed_start = r + 1
            while seed_start < seed_end and grid[seed_start][left] == 0:
                seed_start += 1
            pat = [grid[rr][left] for rr in range(seed_start, seed_end + 1)]
            for c in spine:
                for i, value in enumerate(pat):
                    rr = r + 1 + i
                    if rr < h:
                        out[rr][c] = value
    return out
